package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsTax decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsIncEd string // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var TaxRecData TaxRec

var taxFile *os.File
var taxScanner *bufio.Scanner

func init() {
	WsEofFlag = "N"
	WsTax = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalTax = decimal.NewFromInt(0)
	WsCount = 0
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func parseIncome(field string) decimal.Decimal {
	t := strings.TrimSpace(field)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	neg := false
	if t[0] == '+' || t[0] == '-' {
		if t[0] == '-' {
			neg = true
		}
		t = t[1:]
		if t == "" {
			return decimal.NewFromInt(0)
		}
	}
	// digits only with implied V99; ignore any other chars except digits
	var n int64 = 0
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		} else if ch == ' ' {
			continue
		} else {
			continue
		}
	}
	d := decimal.New(n, -2)
	if neg {
		d = d.Neg()
	}
	return d
}

func fitPic(v decimal.Decimal, intDigits int) decimal.Decimal {
	scaled := v.Shift(2).Truncate(0).IntPart()
	var mod int64 = 1
	for i := 0; i < intDigits+2; i++ {
		mod *= 10
	}
	r := scaled % mod
	return decimal.New(r, -2)
}

func formatEdited(v decimal.Decimal, picture string) string {
	dot := strings.Index(picture, ".")
	var intPic, decPic string
	if dot >= 0 {
		intPic = picture[:dot]
		decPic = picture[dot+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	decSlots := 0
	for _, c := range decPic {
		if c == 'Z' || c == '9' {
			decSlots++
		}
	}
	q := v.Truncate(int32(decSlots))
	if q.IsNegative() && q.IsZero() {
		q = decimal.NewFromInt(0)
	}
	aq := q
	if aq.IsNegative() {
		aq = aq.Abs()
	}
	intPart := aq.Truncate(0)
	fracPart := aq.Sub(intPart).Shift(int32(decSlots)).Truncate(0)
	intVal := intPart.IntPart()
	fracVal := fracPart.IntPart()
	var pow10 int64 = 1
	for i := 0; i < intSlots; i++ {
		pow10 *= 10
	}
	if pow10 != 0 && intSlots > 0 {
		intVal = intVal % pow10
		if intVal < 0 {
			intVal = -intVal
		}
	}
	if fracVal < 0 {
		fracVal = -fracVal
	}
	digits := ""
	if intSlots > 0 {
		digits = fmt.Sprintf("%0*d", intSlots, intVal)
	}
	runes := []rune(intPic)
	resInt := make([]rune, len(runes))
	dIdx := 0
	stillSuppress := true
	for i, ch := range runes {
		if ch == 'Z' || ch == '9' {
			d := byte('0')
			if dIdx < len(digits) {
				d = digits[dIdx]
			}
			dIdx++
			if ch == 'Z' {
				if stillSuppress {
					if d == '0' {
						resInt[i] = ' '
					} else {
						resInt[i] = rune(d)
						stillSuppress = false
					}
				} else {
					resInt[i] = rune(d)
				}
			} else {
				resInt[i] = rune(d)
				stillSuppress = false
			}
		} else if ch == ',' {
			if stillSuppress {
				resInt[i] = ' '
			} else {
				resInt[i] = ','
			}
		} else {
			resInt[i] = ch
		}
	}
	intStr := string(resInt)
	if dot >= 0 {
		decStr := ""
		if decSlots > 0 {
			decStr = fmt.Sprintf("%0*d", decSlots, fracVal)
		}
		return intStr + "." + decStr
	}
	return intStr
}

func MainPara() {
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	taxScanner = bufio.NewScanner(taxFile)
	// allow long lines; default is fine for 13 bytes but enlarge anyway
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	taxScanner.Buffer(buf, maxCap)
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	taxFile.Close()
	if err := taxScanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount%1000)
	fmt.Fprintf(os.Stdout, "TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func ReadPara() {
	if taxScanner.Scan() {
		line := taxScanner.Text()
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		id := line[0:5]
		incStr := line[5:13]
		TaxRecData.TrId = id
		TaxRecData.TrIncome = parseIncome(incStr)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	limit1 := decimal.NewFromInt(10000)
	limit2 := decimal.NewFromInt(40000)
	rate10 := decimal.New(10, -2)
	rate20 := decimal.New(20, -2)
	rate30 := decimal.New(30, -2)
	const1000 := decimal.NewFromInt(1000)
	const7000 := decimal.NewFromInt(7000)
	const10000 := decimal.NewFromInt(10000)
	const40000 := decimal.NewFromInt(40000)
	inc := TaxRecData.TrIncome
	var tax decimal.Decimal
	if inc.Cmp(limit1) <= 0 {
		tax = inc.Mul(rate10)
		tax = tax.Round(2)
		tax = fitPic(tax, 7)
	} else if inc.Cmp(limit2) <= 0 {
		diff := inc.Sub(const10000)
		tax = const1000.Add(diff.Mul(rate20))
		tax = tax.Round(2)
		tax = fitPic(tax, 7)
	} else {
		diff := inc.Sub(const40000)
		tax = const7000.Add(diff.Mul(rate30))
		tax = tax.Round(2)
		tax = fitPic(tax, 7)
	}
	WsTax = tax
	net := inc.Sub(WsTax).Truncate(2)
	net = fitPic(net, 7)
	WsNet = net
	tot := WsTotalTax.Add(WsTax).Truncate(2)
	tot = fitPic(tot, 9)
	WsTotalTax = tot
	WsCount = (WsCount + 1) % 1000
	WsIncEd = formatEdited(inc, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Fprintf(os.Stdout, "%s %s %s %s\n", TaxRecData.TrId, WsIncEd, WsTaxEd, WsNetEd)
	ReadPara()
}

func main() {
	MainPara()
}
